package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.period.PeriodGuard;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.settings.SettingsRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

/** For every plan on the sheet, in the order they were added, make a DRAFT claim with the plan's amount for each
 *  plan date (the start, then every N days; or monthly on its day) up to the end and the sheet's today that has none yet and is not in one of
 *  the plan's pauses (such a date is skipped for good), dated that day
 *  with an empty note, written as CLAIM_ADDED. Each is checked by the claim form's rules: a date the form refuses
 *  is skipped (nothing written) and tried again next time. A plan naming a descendant sheet makes its claims for
 *  the person of the same name on that sheet (none when there is none, or that sheet is archived), by that sheet's
 *  rules and written in that sheet's audit; the plan still counts them. Answers how many were made. A viewer's makes none
 *  (nothing written); an archived sheet refuses it. */
public class GeneratePlanClaims {
    public void generate(@PathVariable("sheetId") String sheetId, ServerHttpConnection connection,
            PlanRepository plans, ClaimRepository claims, SheetRepository sheets, PeriodRepository periods,
            PersonRepository people, SettingsRepository settings, Audit audit, Rollup rollup, Out<GenerateResult> result)
            throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!plans.lockSheet(id)) {
            throw new BadRequestException("no such sheet");
        }
        if (settings.archived(id)) {
            throw new BadRequestException("the sheet is archived");
        }
        if (settings.role(id, by).equals(SettingsRepository.VIEWER)) {
            result.set(new GenerateResult(0));
            return;
        }
        LocalDate today = sheets.today(id);
        int made = 0;
        for (Plan plan : plans.list(id)) {
            String name = plans.personName(id, plan.personId());
            if (name == null) {
                continue;
            }
            // a plan naming a descendant sheet makes its claims for the person of the same name there
            String target = plan.sheet() == null ? id : plan.sheet();
            Long personId = plan.sheet() == null ? Long.valueOf(plan.personId()) : plans.personNamed(target, name);
            if (personId == null || (plan.sheet() != null && settings.archived(target))) {
                continue;
            }
            Set<LocalDate> done = plans.madeOn(plan.id());
            LocalDate end = LocalDate.parse(plan.end());
            LocalDate last = today != null && today.isBefore(end) ? today : end;
            BigDecimal amount = new BigDecimal(plan.amount());
            for (LocalDate on : dates(plan, last)) {
                if (done.contains(on) || plan.skips(on)) {
                    continue;
                }
                try {
                    PeriodGuard.open(periods, target, claims.dueBy(target, personId, on));
                    people.claimAllowed(target, personId, on);
                } catch (BadRequestException refused) {
                    continue;
                }
                Rollup.Snapshot before = rollup.take(target);
                Claim added = claims.add(target, personId, amount, on, "", null);
                claims.log(target, added.id(), by);
                plans.made(id, plan.id(), on, added.id());
                audit.record("CLAIM_ADDED sheet=" + target + " by=" + by + " person=" + name
                        + " amount=" + added.amount() + " date=" + added.date());
                if (added.lateEntry()) {
                    audit.record("LATE_ENTRY sheet=" + target + " by=" + by + " person=" + name
                            + " amount=" + added.amount() + " date=" + added.date());
                }
                rollup.record(target, by, before);
                made++;
            }
        }
        result.set(new GenerateResult(made));
    }

    /** A plan's dates up to last, in order: the start then every N days, or (monthly) that day in every month
     *  from the start's month, falling on the month's last day when beyond it, those before the start left out. */
    private static List<LocalDate> dates(Plan plan, LocalDate last) {
        List<LocalDate> dates = new ArrayList<>();
        LocalDate start = LocalDate.parse(plan.start());
        if (plan.day() == null) {
            for (LocalDate on = start; !on.isAfter(last); on = on.plusDays(plan.every())) {
                dates.add(on);
            }
            return dates;
        }
        for (YearMonth month = YearMonth.from(start); !month.atDay(1).isAfter(last); month = month.plusMonths(1)) {
            LocalDate on = month.atDay(Math.min(plan.day(), month.lengthOfMonth()));
            if (!on.isBefore(start) && !on.isAfter(last)) {
                dates.add(on);
            }
        }
        return dates;
    }
}
-- A person's plans: an amount (more than 0.00, two decimals), a start date, an interval in days (1 or
-- more) and an end date (not before the start). Generating makes a DRAFT claim for each plan date (the
-- start, then every N days, up to the end and the sheet's today) that has none yet; plan_claim keeps the
-- dates a plan has made a claim for. Listed in the order they were added (by id).
CREATE TABLE plan (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(14, 2) NOT NULL CHECK (amount > 0),
    start_date DATE           NOT NULL,
    every_days INT            NOT NULL CHECK (every_days >= 1),
    end_date   DATE           NOT NULL
);
CREATE INDEX plan_sheet ON plan (sheet_id, id);

CREATE TABLE plan_claim (
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    plan_id  BIGINT       NOT NULL REFERENCES plan (id),
    on_date  DATE         NOT NULL,
    claim_id BIGINT       NOT NULL,
    PRIMARY KEY (plan_id, on_date)
);
CREATE INDEX plan_claim_sheet ON plan_claim (sheet_id);
-- A plan's amount changes, in the order made: the day (the sheet's today when changed) and the new amount (more
-- than 0.00, two decimals). The plan's amount is kept as the latest; claims generated from then on take it, claims
-- already generated keep theirs.
CREATE TABLE plan_change (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    plan_id    BIGINT         NOT NULL REFERENCES plan (id),
    changed_on DATE           NOT NULL,
    amount     DECIMAL(14, 2) NOT NULL CHECK (amount > 0)
);
CREATE INDEX plan_change_plan ON plan_change (plan_id, id);
CREATE INDEX plan_change_sheet ON plan_change (sheet_id);
-- A plan may name one of its sheet's descendants (a sheet whose parent, or that one's parent and so on, is the
-- plan's sheet); null when it names none. Its claims are then generated for the person of the same name on that
-- sheet (none when there is no such person), by that sheet's rules and written in that sheet's audit.
ALTER TABLE plan ADD COLUMN target_sheet_id VARCHAR(200);
-- A plan runs either every N days (every_days set) or monthly on a day of the month, 1 to 31 (day_of_month set):
-- that day in every month from the start's month, a day beyond the month's length falling on its last day,
-- dates before the start left out. Exactly one of the two is set.
ALTER TABLE plan ALTER COLUMN every_days SET NULL;
ALTER TABLE plan ADD COLUMN day_of_month INT CHECK (day_of_month BETWEEN 1 AND 31);
