-- A person's plans: an amount (more than 0.00, two decimals), a start date, an interval in days (1 or
-- more) and an end date (not before the start). Generating makes a DRAFT claim for each plan date (the
-- start, then every N days, up to the end and the sheet's today) that has none yet; plan_claim keeps the
-- dates a plan has made a claim for. Listed in the order they were added (by id).
CREATE TABLE plan (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(14, 2) NOT NULL CHECK (amount > 0),
    start_date DATE           NOT NULL,
    every_days INT            NOT NULL CHECK (every_days >= 1),
    end_date   DATE           NOT NULL
);
CREATE INDEX plan_sheet ON plan (sheet_id, id);

CREATE TABLE plan_claim (
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    plan_id  BIGINT       NOT NULL REFERENCES plan (id),
    on_date  DATE         NOT NULL,
    claim_id BIGINT       NOT NULL,
    PRIMARY KEY (plan_id, on_date)
);
CREATE INDEX plan_claim_sheet ON plan_claim (sheet_id);
-- A plan's amount changes, in the order made: the day (the sheet's today when changed) and the new amount (more
-- than 0.00, two decimals). The plan's amount is kept as the latest; claims generated from then on take it, claims
-- already generated keep theirs.
CREATE TABLE plan_change (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    plan_id    BIGINT         NOT NULL REFERENCES plan (id),
    changed_on DATE           NOT NULL,
    amount     DECIMAL(14, 2) NOT NULL CHECK (amount > 0)
);
CREATE INDEX plan_change_plan ON plan_change (plan_id, id);
CREATE INDEX plan_change_sheet ON plan_change (sheet_id);
-- A plan may name one of its sheet's descendants (a sheet whose parent, or that one's parent and so on, is the
-- plan's sheet); null when it names none. Its claims are then generated for the person of the same name on that
-- sheet (none when there is no such person), by that sheet's rules and written in that sheet's audit.
ALTER TABLE plan ADD COLUMN target_sheet_id VARCHAR(200);
-- A plan runs either every N days (every_days set) or monthly on a day of the month, 1 to 31 (day_of_month set):
-- that day in every month from the start's month, a day beyond the month's length falling on its last day,
-- dates before the start left out. Exactly one of the two is set.
ALTER TABLE plan ALTER COLUMN every_days SET NULL;
ALTER TABLE plan ADD COLUMN day_of_month INT CHECK (day_of_month BETWEEN 1 AND 31);
